const svgVariants: Variants = {
  normal: { transform: 'translate(0px, 0px)' },
  animate: {
    transform: [
      'translate(0px, 0px)',
      'translate(-0.8px, -0.35px)',
      'translate(0px, -1.1px)',
      'translate(0.9px, -0.3px)',
